fn solve(input: Vec<char>) -> Vec<char> {
    // Requires that the input vector has exactly 4 characters representing digits
    // and that each character is a valid digit ('0' to '9').
    // This ensures that we can safely convert them to digits.
    assert!(input.len() == 4);
    for &c in &input {
        assert!(c.is_digit(10));
    }

    // Extract the digits from the input
    let d1 = input[0].to_digit(10).unwrap();
    let d2 = input[1].to_digit(10).unwrap();
    let d3 = input[2].to_digit(10).unwrap();
    let d4 = input[3].to_digit(10).unwrap();

    // Possible operators
    let operators = ['+', '-'];

    // Iterate through all combinations of operators
    for &op1 in &operators {
        for &op2 in &operators {
            for &op3 in &operators {
                // Calculate the result based on the current combination of operators
                let result = match op1 {
                    '+' => d1 + d2,
                    '-' => d1 - d2,
                    _ => unreachable!(),
                };
                let result = match op2 {
                    '+' => result + d3,
                    '-' => result - d3,
                    _ => unreachable!(),
                };
                let result = match op3 {
                    '+' => result + d4,
                    '-' => result - d4,
                    _ => unreachable!(),
                };

                // Check if the result equals 7
                if result == 7 {
                    // Construct the output
                    let mut output = Vec::new();
                    output.push(input[0]);
                    output.push(op1);
                    output.push(input[1]);
                    output.push(op2);
                    output.push(input[2]);
                    output.push(op3);
                    output.push(input[3]);
                    output.push('=');
                    output.push('7');
                    output.push('\n');
                    return output;
                }
            }
        }
    }

    // If no valid expression is found, return an empty vector (this should not happen as per problem statement)
    Vec::new()
}

